11	    static boolean isCyclic(List<? extends List<Integer>> adjacencyList) {
12	        return hasCycle(adjacencyList);
13	    }
14	
15	    private static boolean hasCycle(List<? extends List<Integer>> adjacencyList) {
16	        int vertexCount = adjacencyList.size();
17	        int[] inDegrees = calculateInDegrees(adjacencyList, vertexCount);
18	        Deque<Integer> zeroInDegreeVertices = findZeroInDegreeVertices(inDegrees);
19	
20	        int visitedCount = 0;
21	
22	        while (!zeroInDegreeVertices.isEmpty()) {
23	            int vertex = zeroInDegreeVertices.removeFirst();
24	            visitedCount++;
25	
26	            for (int neighbor : adjacencyList.get(vertex)) {
27	                inDegrees[neighbor]--;
28	                if (inDegrees[neighbor] == 0) {
29	                    zeroInDegreeVertices.addLast(neighbor);
30	                }
31	            }
32	        }
33	
34	        return visitedCount != vertexCount;
35	    }
36	
37	    private static int[] calculateInDegrees(
38	            List<? extends List<Integer>> adjacencyList,
39	            int vertexCount
40	    ) {
41	        int[] inDegrees = new int[vertexCount];
42	
43	        for (int vertex = 0; vertex < vertexCount; vertex++) {
44	            for (int neighbor : adjacencyList.get(vertex)) {
45	                validateVertex(neighbor, vertexCount);
46	                inDegrees[neighbor]++;
47	            }
48	        }
49	
50	        return inDegrees;
51	    }
52	
53	    private static Deque<Integer> findZeroInDegreeVertices(int[] inDegrees) {
54	        Deque<Integer> vertices = new ArrayDeque<>();
55	
56	        for (int vertex = 0; vertex < inDegrees.length; vertex++) {
57	            if (inDegrees[vertex] == 0) {
58	                vertices.addLast(vertex);
59	            }
60	        }
61	
62	        return vertices;
63	    }
