65	    static void addEdge(List<? extends List<Integer>> adjacencyList, int source, int destination) {
66	        validateVertex(source, adjacencyList.size());
67	        validateVertex(destination, adjacencyList.size());
68	        adjacencyList.get(source).add(destination);
69	    }
70	
71	    private static void validateVertex(int vertex, int vertexCount) {
72	        if (vertex < 0 || vertex >= vertexCount) {
73	            throw new IllegalArgumentException("Vertex out of range: " + vertex);
74	        }
75	    }
